// Agrega automáticamente la barra con el logo de Genética Universal arriba
// de la primera página de cada ficha PDF que se sube desde el admin. No
// toca el color del contenido original del reporte (eso el cliente pidió
// dejarlo tal cual) — solo agranda la página y dibuja la barra + logo en
// el espacio nuevo, así nunca tapa nada del PDF original.
import { PDFDocument, rgb } from 'pdf-lib';

const HEADER_HEIGHT = 58;
const NAVY = rgb(17 / 255, 16 / 255, 22 / 255);

const ICON_PNG_B64 = '';
const WORDMARK_PNG_B64 = '';

function base64ToBytes(b64) {
  const bin = atob(b64);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  return bytes;
}

export async function addFichaHeader(pdfBytes) {
  const srcDoc = await PDFDocument.load(pdfBytes);
  const pageCount = srcDoc.getPageCount();
  if (pageCount === 0) return pdfBytes;

  const outDoc = await PDFDocument.create();
  const iconImage = await outDoc.embedPng(base64ToBytes(ICON_PNG_B64));
  const wordmarkImage = await outDoc.embedPng(base64ToBytes(WORDMARK_PNG_B64));

  const [embeddedFirstPage] = await outDoc.embedPdf(srcDoc, [0]);
  const firstPage = srcDoc.getPage(0);
  const { width, height } = firstPage.getSize();

  const newPage = outDoc.addPage([width, height + HEADER_HEIGHT]);
  newPage.drawRectangle({ x: 0, y: height, width, height: HEADER_HEIGHT, color: NAVY });

  const iconSize = HEADER_HEIGHT - 16;
  const iconX = 22;
  const iconY = height + (HEADER_HEIGHT - iconSize) / 2;
  newPage.drawImage(iconImage, { x: iconX, y: iconY, width: iconSize, height: iconSize });

  const wordmarkScale = (HEADER_HEIGHT - 24) / wordmarkImage.height;
  const wordmarkWidth = wordmarkImage.width * wordmarkScale;
  const wordmarkHeight = wordmarkImage.height * wordmarkScale;
  const wordmarkX = iconX + iconSize + 12;
  const wordmarkY = height + (HEADER_HEIGHT - wordmarkHeight) / 2;
  newPage.drawImage(wordmarkImage, { x: wordmarkX, y: wordmarkY, width: wordmarkWidth, height: wordmarkHeight });

  newPage.drawPage(embeddedFirstPage, { x: 0, y: 0, width, height });

  if (pageCount > 1) {
    const restIndices = Array.from({ length: pageCount - 1 }, (_, i) => i + 1);
    const restPages = await outDoc.copyPages(srcDoc, restIndices);
    restPages.forEach((p) => outDoc.addPage(p));
  }

  return outDoc.save();
}
